insert into public.books (slug, title, author, category_id, description, price, isbn, status, sort_order) values ('القانون-الدولي-للبحار-468', 'القانون الدولي للبحار', 'محمد الشقلاف', (select id from public.categories where slug = 'law'), 'كتاب قانوني يركز على موضوع «القانون الدولي للبحار». يقدم معالجة مرتبطة بالمجال القانوني كما يدل عنوانه، وهو مناسب للطلاب والباحثين والمهتمين بالدراسات القانونية.', 30.00, 'توزيع', null, 468);
insert into public.books (slug, title, author, category_id, description, price, isbn, status, sort_order) values ('شذرات-من-تاريخ-كباو-469', 'شذرات من تاريخ كباو', 'معيوف حلاسة', (select id from public.categories where slug = 'history'), 'كتاب تاريخي حول «شذرات من تاريخ كباو». يسلط الضوء على الموضوع التاريخي المشار إليه في العنوان، ويمكن أن يكون مدخلًا مفيدًا للمهتمين بالتاريخ والدراسات المرتبطة به.', 45.00, '9789959983404', null, 469);
