insert into public.books (slug, title, author, category_id, description, price, isbn, status, sort_order) values ('نباتات-الزينة-الليبية-471', 'نباتات الزينة الليبية', 'عبد الله القاضي', (select id from public.categories where slug = 'botany'), 'كتاب متخصص في النباتات حول «نباتات الزينة الليبية». يتناول الموضوع النباتي الذي يشير إليه العنوان، ومناسب للمهتمين بالنباتات والعلوم الزراعية والطبيعية.', 65.00, null, null, 471);
insert into public.books (slug, title, author, category_id, description, price, isbn, status, sort_order) values ('flora-of-libya-1-150-472', 'flora of libya 1-150', 'dr abdalla ghadi', (select id from public.categories where slug = 'general'), 'كتاب بعنوان «flora of libya 1-150» للمؤلف dr abdalla ghadi. لا يتوفر في البيانات تصنيف واضح له، لذلك يقتصر الوصف على تقديمه بوصفه عنوانًا ضمن إصدارات دار الحكمة دون افتراض تفاصيل غير متاحة.', 500.00, null, null, 472);